const routes = ['/ops/radar', '/ops/operations', '/ops/launchpad', '/ops/rules'];
for (const route of routes) {
  await page.goto(route);
  await expect(page).toHaveURL(new RegExp(route));
  const broken = await page.evaluate(() => {
    // classes whose font-size rule is scoped to "div.<class>"
    const classes = new Set();
    for (const sheet of Array.from(document.styleSheets)) {
      let rules = [];
      try { rules = Array.from(sheet.cssRules); } catch (e) { continue; }
      const walk = (list) => {
        for (const r of list) {
          if (r.cssRules && !r.selectorText) { walk(Array.from(r.cssRules)); continue; }
          if (!r.selectorText || !r.style || !r.style.fontSize) continue;
          for (const sel of r.selectorText.split(',')) {
            const m = sel.trim().match(/(?:^|[\s>+~])div\.([\w-]+)\s*$/);
            if (m) classes.add(m[1]);
          }
        }
      };
      walk(rules);
    }
    const out = [];
    for (const c of classes) {
      for (const span of Array.from(document.querySelectorAll('span.' + c))) {
        const probe = document.createElement('div');
        probe.className = c;
        span.parentElement.appendChild(probe);
        const want = getComputedStyle(probe).fontSize;
        probe.remove();
        const got = getComputedStyle(span).fontSize;
        if (want !== got) out.push(c + ': span ' + got + ' vs div ' + want);
      }
    }
    return out;
  });
  expect(broken).toEqual([]);
}
